def load_j_runner():
    spec = importlib.util.spec_from_file_location("round2j_nagi_quality_ceiling", ROOT / "scripts" / "run_round2j_nagi_quality_ceiling.py")
    if spec is None or spec.loader is None:
        raise RuntimeError("cannot load Round 2J runner")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


