def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def build_html_q(manifest: dict[str, dict[str, str]]) -> str:
    markup = J.build_html_j(manifest)
    hero = f'''<section class="hero" id="top" data-viewport-id="V01" data-motion-signature="DETAIL_TO_RELATIONSHIP"><div class="hero-media"><img src="/{manifest["A01"]["output"]}" alt="人と人が穏やかに向き合うサービスイメージ"></div><div class="hero-content"><p class="hero-kicker">なぎのみらい｜福岡市</p><h1 class="headline" data-editorial-role="hero_headline"><span>人と関わるサービスを、</span><span>分からないまま選ばない。</span></h1><p class="lead">ドライヘッドスパ、ヘッドスパスクール、ヒーリングサロン。料金・時間・流れを確認しながら、気になるサービスについて相談できます。</p><ul class="hero-services"><li>ドライヘッドスパ</li><li>ヘッドスパスクール</li><li>ヒーリングサロン</li></ul><div class="actions"><a class="link primary" href="#entry">サービスを選ぶ ↓</a><a class="link" href="{INSTAGRAM}" target="_blank" rel="noreferrer">Instagramで相談する ↗</a></div></div><p class="hero-motion-note">DETAIL → RELATIONSHIP</p></section><section'''
    markup = re.sub(r'<section class="hero".*?<section', hero, markup, count=1, flags=re.S)
    details = {
        "treatment": {"image": f"/{manifest['A05']['output']}", "alt": "ドライヘッドスパを受ける場面を想起させるサービスイメージ", "intent": "受けたい", "title": "ドライヘッドスパ", "fact": "60分 8,800円 / 90分 12,100円。60〜90分。", "price": "60分 8,800円 / 90分 12,100円", "time": "60〜90分"},
        "school": {"image": f"/{manifest['A06']['output']}", "alt": "ヘッドスパを学ぶ場面を想起させるサービスイメージ", "intent": "学びたい", "title": "ヘッドスパスクール", "fact": "1日講座 33,000円。約5時間。", "price": "1日講座 33,000円", "time": "約5時間"},
        "healing": {"image": f"/{manifest['A07']['output']}", "alt": "ヒーリングについて相談する場面を想起させるサービスイメージ", "intent": "内容を知りたい", "title": "ヒーリングサロン", "fact": "60分 8,800円。約60分。", "price": "60分 8,800円", "time": "約60分"},
    }
    entry = f'''<section class="section entry purpose-selector" id="entry" data-viewport-id="V02" data-interaction="guided-preview-click-lock"><div class="purpose-header"><div><h2 class="headline" data-editorial-role="entry_headline"><span>気になるサービスは、</span><span>どれですか。</span></h2><p class="selector-support"><strong>3つのサービスから、気になるものを選べます。</strong><span>カーソルを合わせると、内容・料金・時間を確認できます。</span></p></div><p class="lead">受けたい、学びたい、内容を知りたい。今の目的に近いサービスから確認できます。</p></div><div class="purpose-layout"><div class="purpose-rows" role="radiogroup" aria-label="サービスを選ぶ"><button class="purpose-row active" data-route="treatment" aria-pressed="true"><span class="route-num">01</span><span><span class="purpose-label" data-lineqa-ignore>ドライヘッドスパ</span><span class="purpose-intent">受けたい</span></span><span class="route-arrow">↗</span></button><button class="purpose-row" data-route="school" aria-pressed="false"><span class="route-num">02</span><span><span class="purpose-label" data-lineqa-ignore>ヘッドスパスクール</span><span class="purpose-intent">学びたい</span></span><span class="route-arrow">↗</span></button><button class="purpose-row" data-route="healing" aria-pressed="false"><span class="route-num">03</span><span><span class="purpose-label" data-lineqa-ignore>ヒーリングサロン</span><span class="purpose-intent">内容を知りたい</span></span><span class="route-arrow">↗</span></button></div><div class="purpose-stage" id="route-note" data-selected-service="treatment"><figure class="choice-visual"><img id="choice-image" src="/{manifest["A05"]["output"]}" alt="ドライヘッドスパを受ける場面を想起させるサービスイメージ"></figure><div class="choice-copy"><p class="choice-intent" id="choice-intent">受けたい</p><h3 id="choice-title">ドライヘッドスパ</h3><p class="choice-fact" id="choice-fact">60分 8,800円 / 90分 12,100円。60〜90分。</p></div></div></div></section><section'''
    markup = re.sub(r'<section class="section entry.*?<section class="section(?: dark)? before"', entry + ' class="section dark before"', markup, count=1, flags=re.S)
    before = f'''<section class="section before" id="before-touch" data-viewport-id="V03" data-price-section="before"><div class="before-layout"><div><h2 class="headline" data-editorial-role="process_headline"><span>料金も、時間も、</span><span>流れも確認できます。</span></h2><p class="lead">相談する前に、サービスを選ぶために必要な情報を確認できます。</p><div class="before-facts"><div class="before-fact"><strong>サービス</strong><p>受ける・学ぶ・内容を知る。3つの目的から選べます。</p></div><div class="before-fact"><strong>料金・時間</strong><p>60分 8,800円 / 90分 12,100円。1日講座 33,000円、約5時間。</p></div><div class="before-fact"><strong>相談先</strong><p>公式Instagram @happyfuture_02から相談できます。</p></div></div></div><figure class="before-visual"><img src="/{manifest["A02"]["output"]}" alt="二人が穏やかに向き合い相談する場面を想起させるサービスイメージ"></figure></div></section><section'''
    markup = re.sub(r'<section class="section(?: dark)? before".*?<section class="section service treatment"', before + ' class="section service treatment"', markup, count=1, flags=re.S)
