    markup = markup.replace('<h2 data-editorial-role="school_headline">学ぶ</h2>', '<h2 data-editorial-role="school_headline"><span>スクールを</span><span>選ぶ前に。</span></h2>')
    markup = markup.replace('<h2 data-editorial-role="healing_headline">知る</h2>', '<h2 data-editorial-role="healing_headline"><span>まず、ヒーリングの</span><span>内容から。</span></h2>')
    markup = markup.replace('触れる内容と、最初に確認したいことを相談できます。', '何をするか、料金、時間、流れを確認してから相談できます。')
    markup = markup.replace('実技デモ、練習、振り返り。学ぶ入口の内容を相談できます。', '学ぶ内容、講座の時間、料金、練習の流れを確認できます。')
    markup = markup.replace('方法を決めつけず、過ごし方と相談内容を確認できます。', 'ヒーリングが何なのか、過ごし方と相談内容を確認できます。')
    markup = markup.replace('<section class="section guide"', '<section class="section guide" data-growth-role="comparison"', 1)
    markup = markup.replace('<section class="section booking"', '<section class="section booking" data-growth-role="contact"', 1)
    booking_re = re.compile(r'<section class="section booking".*?<section class="section closing"', re.S)
    booking = f'''<section class="section booking" id="booking" data-viewport-id="V10" data-growth-role="contact"><div class="booking-grid"><div class="booking-title"><h2 class="headline" data-editorial-role="booking_headline"><span>3つのサービスを、</span><span>1つの相談先へ。</span></h2><p class="lead booking-copy">気になるサービスが決まっていなくても、公式Instagramで相談できます。選んだサービスは、相談の入口として伝えられます。</p><div class="path-merge" aria-label="3つのサービスからInstagramへ"><div class="merge-path"><span>ドライヘッドスパ</span><span>↘</span></div><div class="merge-path"><span>ヘッドスパスクール</span><span>↘</span></div><div class="merge-path"><span>ヒーリングサロン</span><span>↘</span></div></div><div id="selected-token" class="selected-token" data-service-token><span>選択中</span><strong>ドライヘッドスパ</strong></div></div><div class="contact"><span class="small">共通の相談先</span><strong>@happyfuture_02</strong><a class="link" href="{INSTAGRAM}" target="_blank" rel="noreferrer">公式Instagramで相談する ↗</a></div></div></section><section'''
    markup = booking_re.sub(booking, markup, count=1)
    markup = markup.replace('<span>分からないことから、</span><span>相談してください。</span>', '<span>気になることが一つあれば、</span><span>そこから相談できます。</span>')
    markup = markup.replace('入口を見る', 'サービスを選ぶ').replace('3つの入口を見る', '3つのサービスを選ぶ').replace('三つの入口', '3つのサービス').replace('各入口に掲載', '各サービスに掲載').replace('どの入口', 'どのサービス').replace('入口', 'サービス')
    markup = re.sub(r'<p class="eyebrow">.*?</p>', '', markup, flags=re.S)
